{"contents":[{"uri":"montagent://schema/def/Run.json","mimeType":"application/json","text":"{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "text": {
      "type": "string",
      "description": "UTF-8, NFC, raw characters — the serializer never emits `\\uXXXX` above U+007F,\nbecause escaping destroys the unique-substring guarantee uniformly rather than\noccasionally. Whitespace inside a run is content: the fixture's `cobweb  -  cobweb`\ncarries deliberate double spaces that no tidying pass may touch."
    },
    "font": {
      "type": "string",
      "description": "Style deltas over the element's base style. Every one is optional because a delta\nthat is absent is a delta that was not made."
    },
    "size": {
      "type": "integer",
      "format": "int64"
    },
    "color": {
      "$ref": "montagent://schema/def/Colour.json"
    },
    "stroke": {
      "description": "ADR-0014: on text the stroke falls **outside** the glyph contour and grows into the\ndeclared box rather than enlarging the element.",
      "$ref": "montagent://schema/def/Colour.json"
    },
    "stroke_width": {
      "type": "integer",
      "format": "int64"
    },
    "dir": {
      "description": "A per-run direction override with **isolate** semantics only — never LRO/RLO, which\nexist for legacy data and turn \"my text renders backwards\" into an unfalsifiable\nmystery (ADR-0007).",
      "$ref": "montagent://schema/def/Dir.json"
    },
    "highlight": {
      "description": "The timed window during which this run wears a different style (ADR-0048). Every\nhighlighted word is its own run, and a run carries at most one window — letting one\nrun span several words would need sub-run character offsets, which a later text\nedit invalidates silently while leaving the JSON structurally valid.",
      "$ref": "montagent://schema/def/Highlight.json"
    }
  },
  "required": [
    "text"
  ],
  "description": "One stretch of a text element's content.\n\nAlways an array, never a bare string: ADR-0007 rejected the shorthand because *\"it\noptimises every edit except the one that actually occurred\"* — adding a second style to\na flat string is a shape change that retypes the original text at precisely the moment\nthe author is doing something typographically delicate."
}
"}]}

